INSERT INTO site_settings (id, hero_tagline) VALUES (1, 'Innovate. Engineer. Evolve.') ON CONFLICT (id) DO UPDATE SET hero_tagline = EXCLUDED.hero_tagline;
INSERT INTO about_content (id, intro_headline, intro_summary, vision_text, mission_text, team_photo_url, team_photo_caption) VALUES (1, 'THE LEGACY OF UNTAMED ENDURANCE', 'Team Red Baron is Pimpri Chinchwad College of Engineering’s official collegiate offroad racing team. We design, manufacture, test, and race high-performance All-Terrain Vehicles (ATVs) for national BAJA SAE India competitions.', 'To become a leading student motorsports team recognized for innovation, technical excellence, and teamwork in designing and developing high-performance electric All-Terrain Vehicles, while representing the institution successfully at national and international competitions such as eBAJA SAE India and Baja SAE International.', 'To design and manufacture reliable, competitive electric ATVs through innovative engineering, while developing technical, leadership, and teamwork skills through hands-on learning, representing our institution with excellence, and advancing sustainable automotive technologies.', 'https://axzwucvnrjtenvvrxfew.supabase.co/storage/v1/object/public/trb-media/team/IMG_9368.jpg', 'Team Red Baron Squad') ON CONFLICT (id) DO UPDATE SET intro_headline = EXCLUDED.intro_headline;
INSERT INTO contact_info (id, email, address, instagram_url, linkedin_url, youtube_url, twitter_url) VALUES (1, 'teamredbaron07@gmail.com', 'Pimpri Chinchwad College of Engineering (PCCOE)\nSector 26, Pradhikaran, Nigdi, Pune, Maharashtra 411044', 'https://www.instagram.com/team_red_baron?igsh=MWFwcnl6Y2ZlZzlwdA==', 'https://www.linkedin.com/company/team-red-baron/posts/?feedView=all', 'https://youtube.com/@teamredbaron4316?feature=shared', '') ON CONFLICT (id) DO UPDATE SET email = EXCLUDED.email;
  INSERT INTO vehicles (year, vehicle_name, chassis_serial, subtitle, rank_text, badge_text, icon_key, description, image_url, status_badge, background_video_url, timeline_order) VALUES ('2026', 'Albatros XIV', 'TRB-2026-X14', 'AIR 3 Overall Podium & BEST 4WD', 'AIR 3 National', 'BEST 4WD', 'ShieldCheck', 'Secured AIR 3 overall and AIR 4 in both Statics and Dynamics, emerging as the best-performing 4WD vehicle and continuing the team’s engineering evolution.', 'https://axzwucvnrjtenvvrxfew.supabase.co/storage/v1/object/public/trb-media/assets/images/albatros-xiii.png', 'RACE READY', 'https://axzwucvnrjtenvvrxfew.supabase.co/storage/v1/object/public/trb-media/assets/videos/trb_bg_optimized.mp4', 0) RETURNING id INTO v_id;
