  INSERT INTO vehicles (year, vehicle_name, chassis_serial, subtitle, rank_text, badge_text, icon_key, description, image_url, status_badge, background_video_url, timeline_order) VALUES ('2023', 'Albatros XII', NULL, 'Advanced IoT Telemetry & Dynamic Rigidity', 'Telemetry Era', 'TELEMETRY ERA', 'Cpu', 'Integrated real-time wireless IoT pitwall telemetry streaming wheel speeds, CVT temperatures, and suspension travel metrics live. Optimized chassis weight reduction by 14% with enhanced torsional stiffness.', 'https://axzwucvnrjtenvvrxfew.supabase.co/storage/v1/object/public/trb-media/images_timeline/2023.png', NULL, NULL, 3) RETURNING id INTO v_id;
