  INSERT INTO vehicles (year, vehicle_name, chassis_serial, subtitle, rank_text, badge_text, icon_key, description, image_url, status_badge, background_video_url, timeline_order) VALUES ('2021', 'Albatros X', NULL, 'First Four-Wheel-Drive (4WD) ATV', '1st AIR Design', '4WD INNOVATION', 'Zap', 'Pioneered Team Red Baron''s first custom 4WD transfer case and custom front differential setup. Dominated BAJA SAE India 2021 Overall Design Standings and earned 2nd Runner-Up Cost internationally.', 'https://axzwucvnrjtenvvrxfew.supabase.co/storage/v1/object/public/trb-media/images_timeline/2021.avif', NULL, NULL, 5) RETURNING id INTO v_id;
